{"path":"lib/books.js","content":"import { promises as fs } from "node:fs";
import path from "node:path";
import { randomUUID } from "node:crypto";

// Where books are stored. Override with BOOKS_FILE (used by tests).
function dataFile() {
  return process.env.BOOKS_FILE || path.join(process.cwd(), "data", "books.json");
}

async function readAll() {
  try {
    const raw = await fs.readFile(dataFile(), "utf8");
    const parsed = JSON.parse(raw);
    return Array.isArray(parsed) ? parsed : [];
  } catch (err) {
    if (err.code === "ENOENT") return [];
    throw err;
  }
}

async function writeAll(books) {
  const file = dataFile();
  await fs.mkdir(path.dirname(file), { recursive: true });
  // Write to a temp file and rename so a crash never leaves a half-written file.
  const tmp = `${file}.${process.pid}.${Date.now()}.tmp`;
  await fs.writeFile(tmp, JSON.stringify(books, null, 2) + "\n", "utf8");
  await fs.rename(tmp, file);
}

// Serialize read-modify-write operations so concurrent requests don't clobber each other.
let queue = Promise.resolve();
function update(fn) {
  const run = queue.then(async () => {
    const books = await readAll();
    const result = await fn(books);
    await writeAll(books);
    return result;
  });
  queue = run.catch(() => {});
  return run;
}

export async function listBooks() {
  return readAll();
}

export async function getBook(id) {
  const books = await readAll();
  return books.find((b) => b.id === id) ?? null;
}

export async function addBook({ title, author, notes }) {
  title = String(title ?? "").trim();
  author = String(author ?? "").trim();
  notes = String(notes ?? "").trim();
  if (!title) throw new Error("Title is required");

  const book = {
    id: randomUUID(),
    title,
    author,
    notes,
    status: "reading",
    addedAt: new Date().toISOString(),
    finishedAt: null,
  };
  return update((books) => {
    books.push(book);
    return book;
  });
}

export async function markFinished(id) {
  return update((books) => {
    const book = books.find((b) => b.id === id);
    if (!book) return null;
    if (book.status !== "finished") {
      book.status = "finished";
      book.finishedAt = new Date().toISOString();
    }
    return book;
  });
}

export async function updateNotes(id, notes) {
  return update((books) => {
    const book = books.find((b) => b.id === id);
    if (!book) return null;
    book.notes = String(notes ?? "").trim();
    return book;
  });
}
