{"path":"lib/books.test.js","content":"import { describe, it, expect, beforeEach } from "vitest";
import { mkdtempSync, readFileSync } from "node:fs";
import { tmpdir } from "node:os";
import path from "node:path";
import { addBook, getBook, listBooks, markFinished, updateNotes } from "./books.js";

beforeEach(() => {
  const dir = mkdtempSync(path.join(tmpdir(), "books-"));
  process.env.BOOKS_FILE = path.join(dir, "books.json");
});

describe("books store", () => {
  it("starts empty when the file doesn't exist", async () => {
    expect(await listBooks()).toEqual([]);
  });

  it("adds a book and persists it to the JSON file", async () => {
    const book = await addBook({ title: "  Dune ", author: "Frank Herbert", notes: "Spice" });
    expect(book.title).toBe("Dune");
    expect(book.status).toBe("reading");
    const onDisk = JSON.parse(readFileSync(process.env.BOOKS_FILE, "utf8"));
    expect(onDisk).toHaveLength(1);
    expect(await getBook(book.id)).toEqual(book);
  });

  it("requires a title", async () => {
    await expect(addBook({ title: "  " })).rejects.toThrow(/title/i);
  });

  it("marks a book finished", async () => {
    const book = await addBook({ title: "Emma" });
    const done = await markFinished(book.id);
    expect(done.status).toBe("finished");
    expect(done.finishedAt).toBeTruthy();
    expect(await markFinished("nope")).toBeNull();
  });

  it("updates notes", async () => {
    const book = await addBook({ title: "Emma" });
    await updateNotes(book.id, "Great");
    expect((await getBook(book.id)).notes).toBe("Great");
  });

  it("does not lose writes when adding concurrently", async () => {
    await Promise.all(Array.from({ length: 20 }, (_, i) => addBook({ title: `B${i}` })));
    expect(await listBooks()).toHaveLength(20);
  });
});
"}

